        bool video=key.ToString()=="video";string text=value.ToString();var source=video&&value.VariantType!=Variant.Type.Nil&&text.Length>0?Video.Call("info",text).AsGodotDictionary():new Settings();if(video&&text.Length>0&&value.VariantType!=Variant.Type.Nil&&source.Count==0)return;if(key.ToString()=="linked_audio_actor"&&text.Length>0){var target=actor_for_id(owner,text);if(target==null||target.Get("type_id").AsString()!="audio"||!can_set_parent(owner,target.Get("id").AsString(),actor.Get("id").AsString()))return;}var before=media_snapshot(owner);var values=actor.Get("values").AsGodotDictionary();var previous=actor_for_id(owner,Get(values,"linked_audio_actor","").ToString());if(video){if(previous!=null){foreach(var item in Actors(owner)){var child=item.As<Resource>();if(child.Get("parent_id").AsString()==previous.Get("id").AsString())child.Set("parent_id",previous.Get("parent_id"));}int index=Actors(owner).IndexOf(previous);Selected(owner).Remove(Clips(owner)[index].As<Resource>().Get("id"));Actors(owner).RemoveAt(index);Clips(owner).RemoveAt(index);}values[new StringName("video")]=value.VariantType!=Variant.Type.Nil?value:Variant.From("");var clip=clip_for_actor_id(owner,actor.Get("id").AsString())!;clip.Set("source_offset",0.0);clip.Set("duration",Get(source,"duration",.1).AsDouble());while(!can_place(owner,clip.Get("id").AsString(),clip.Get("start_time").AsDouble(),clip.Get("duration").AsDouble(),clip.Get("layer").AsInt32()))clip.Set("layer",clip.Get("layer").AsInt32()+1);configure_video_audio(owner,actor);}else{if(previous!=null&&previous.Get("parent_id").AsString()==actor.Get("id").AsString()){previous.Set("parent_id",actor.Get("parent_id"));var clip=clip_for_actor_id(owner,previous.Get("id").AsString())!;while(!can_place(owner,clip.Get("id").AsString(),clip.Get("start_time").AsDouble(),clip.Get("duration").AsDouble(),clip.Get("layer").AsInt32()))clip.Set("layer",clip.Get("layer").AsInt32()+1);}values[key]=text;var replacement=actor_for_id(owner,text);if(replacement!=null){replacement.Set("parent_id",actor.Get("id"));replacement.Set("section_id",actor.Get("section_id"));var clip=clip_for_actor_id(owner,replacement.Get("id").AsString())!;while(!can_place(owner,clip.Get("id").AsString(),clip.Get("start_time").AsDouble(),clip.Get("duration").AsDouble(),clip.Get("layer").AsInt32()))clip.Set("layer",clip.Get("layer").AsInt32()+1);}}commit_media(owner,before,video?"Change Video":"Change Linked Audio Actor");
